const esGmail = $('Normalizar Gmail').isExecuted;
const e = esGmail
  ? $('Normalizar Gmail').item.json
  : $('Normalizar Telegram').item.json;

let datos = {};
try { datos = JSON.parse($json['Datos claves'] || '{}'); } catch (err) {}

const texto = esGmail ? e.mensaje : e.Texto;

// Detecta "soy X", "me llamo X" o "mi nombre es X" en el texto
const m = (texto || '').match(/(?:\bsoy|me llamo|mi nombre es)\s+([A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+)/i);
const nombreDetectado = m ? m[1] : '';

const limpio = (v) => (v && v !== 'No informado') ? v : '';

return {
  json: {
    Session_ID: e.Session_ID,
    Texto: texto,
    Nombre: nombreDetectado || limpio(datos.nombre) || limpio(e.Nombre) || 'No informado',
    Mensajes: Number(datos.mensajes ?? 0) + 1,
    Estado: $json['Estado del caso'] || 'Nuevo',
    Resumen: $json['Resumen consolidado'] || 'Todavía no hay resumen de charlas anteriores.',
    email: esGmail ? e.Session_ID : '',
    asunto: esGmail ? e.asunto : '',
    mensaje: texto,
  },
};

