const limpiar = t => String(t ?? '').replace(/\s+/g, ' ').trim();
const vacio = v => !v || /^(no informado|n\/a|na|-|null|undefined)$/i.test(v);
const titulo = t => t.toLowerCase().replace(/(^|\s)\p{L}/gu, c => c.toUpperCase());
const AVISO = 'Gracias por escribirnos. Tu consulta fue derivada a una persona del equipo, que te va a responder a la brevedad.';

// Si el agente devolvió el JSON como texto, lo convertimos a objeto
let o = $json.output ?? {};
if (typeof o === 'string') {
  try { o = JSON.parse(o.replace(/```json|```/g, '').trim()); } catch (e) { o = {}; }
}

const categoria = limpiar(o.categoria).toUpperCase().replace(/\s/g, '_') || 'REVISION_MANUAL';

let nombre = limpiar(o.nombre);
nombre = vacio(nombre) ? 'No informado' : titulo(nombre);

let contacto = limpiar(o.contacto);
if (vacio(contacto)) {
  contacto = 'No informado';
} else if (contacto.includes('@')) {
  contacto = contacto.toLowerCase().replace(/\s/g, '');
} else {
  const tel = contacto.replace(/[^\d+]/g, '');
  if (tel.replace(/\D/g, '').length >= 6) contacto = tel;
}

let tipo = limpiar(o.tipo_testing).toLowerCase();
if (vacio(tipo)) tipo = 'No informado';

let consulta = limpiar(o.consulta);
if (vacio(consulta)) consulta = 'No informado';

return {
  json: {
    ...$json,
    output: {
      categoria,
      motivo: limpiar(o.motivo) || 'No se pudo interpretar la respuesta del agente',
      nombre,
      contacto,
      tipo_testing: tipo,
      consulta,
      mensaje_usuario: limpiar(o.mensaje_usuario) || AVISO,
    },
  },
};

