const c = $('Armar contexto').item.json;
const limpiar = t => String(t ?? '').replace(/\s+/g, ' ').trim();

const bruto = String($json.text ?? '{}').replace(/```json|```/g, '').trim();
let r = {};
try { r = JSON.parse(bruto); } catch (e) {}

const puntos = (Array.isArray(r.puntos_clave) ? r.puntos_clave : [r.puntos_clave])
  .filter(Boolean).map(limpiar);
const accion = limpiar(r.accion_requerida);

return {
  json: {
    Session_ID: c.Session_ID,
    'Fecha de actualizacion': $now.toFormat('yyyy-LL-dd HH:mm'),
    'Resumen consolidado': limpiar(r.asunto_principal) + (puntos.length ? ' — ' + puntos.join('; ') : ''),
    'Estado del caso': accion ? 'Pendiente' : 'En seguimiento',
    'Datos claves': JSON.stringify({ nombre: c.Nombre, mensajes: c.Mensajes, accion_requerida: accion }),
  },
};

const c = $('Armar contexto').item.json;
const previo = c.Resumen.startsWith('Todavía') ? '' : c.Resumen;

return {
  json: {
    Session_ID: c.Session_ID,
    'Fecha de actualizacion': $now.toFormat('yyyy-LL-dd HH:mm'),
    'Resumen consolidado': previo,
    'Estado del caso': c.Estado,
    'Datos claves': JSON.stringify({ nombre: c.Nombre, mensajes: c.Mensajes }),
  },
};

const m = $json.message ?? {};
const limpiar = t => String(t ?? '').replace(/\s+/g, ' ').trim();

return {
  json: {
    Session_ID: limpiar(m.chat?.id),
    Texto: limpiar(m.text),
    Nombre: limpiar(m.from?.first_name),
    Fecha: $now.toFormat('yyyy-LL-dd HH:mm'),
  },
};
